const concertArc={
 concert_1:{title:'작은 공연 준비 ① · 제안',day:15,when:s=>s.stories.includes('ring_board_8'),lines:[['아논','게시판에 공연 얘기가 많이 모였으니까, 작은 특별 공연을 하면 어떨까?'],['타키','공연은 우리가 하고 싶다고 바로 정할 수 있는 게 아냐. RiNG 일정부터 확인해야지.'],['아논','알아. 일단 생각을 말해 본 거야. 게시판 읽고 공연을 궁금해하는 사람도 있었고.'],['타키','그럼 언제 할 건데? 장비랑 다른 밴드 일정도 봐야 해.'],['아논','그건… 아직 생각 못 했어.'],['소요','가능한 날짜와 준비할 일을 먼저 물어보자.'],['아논','응. 나도 필요한 거 찾아볼게. 그냥 말만 하고 끝내긴 싫으니까.'],['토모리','손님들이 여기 남긴 말처럼… 우리도 노래를 남길 수 있으면 좋겠어.'],['타키','응. 그럼 내가 일정부터 알아볼게.']]},
 concert_2:{title:'작은 공연 준비 ② · 일정표',day:16,when:s=>s.stories.includes('concert_1'),lines:[['타키','RiNG에 확인했어. 후보 날짜가 두 개 있어.'],['소요','연습 시간도 포함해서 모두의 일정을 맞춰 보자.'],['아논','나는 둘 다 괜찮아. 아, 잠깐. 한 날은 시험이었지.'],['타키','제대로 확인하고 말해. 연습 시간을 정했다가 또 바꾸면 곤란하잖아.'],['아논','지금 확인하고 있잖아! …이날은 시험 끝나고라 괜찮아.'],['소요','그럼 끝나는 시간도 적어 줄래? 이동할 시간까지 생각해야 하니까.'],['아논','응. 연습실에 몇 시까지 갈 수 있는지 적어 둘게.'],['라나','나는 기타 칠 수 있는 날이면 돼.'],['타키','그러니까 가능한 날을 알려 달라고.'],['토모리','달력에 한 사람씩 표시하면… 보기 쉬울 것 같아.']]},
 concert_3:{title:'작은 공연 준비 ③ · 빈 칸',day:17,when:s=>s.stories.includes('concert_2'),lines:[['소요','다섯 명이 모두 가능한 날짜가 여기 하나 있네.'],['아논','그럼 그날로 확정! 포스터도 만들고, 메뉴도…'],['타키','아직 RiNG에 최종 확인 안 했어. 먼저 그걸 해야지.'],['아논','아, 맞다. 나 너무 앞서갔나.'],['타키','먼저 물어볼 내용을 정리하면 확인하기 쉬울 거야.'],['아논','날짜랑, 준비할 수 있는 시간… 그리고 필요한 장비?'],['소요','카페 쪽 준비도 따로 적어 두자. 공연 시간하고 겹치니까.'],['아논','응. 확인하기 전까지는 아직 확정이라고 말하지 않을게.'],['토모리','기대돼서 그런 거잖아.'],['아논','응. 이번엔 준비부터 제대로 하고 싶어.']]},
 concert_4:{title:'작은 공연 준비 ④ · 전하고 싶은 것',day:18,when:s=>s.stories.includes('concert_3'),lines:[['토모리','어떤 노래를 부르면 좋을지 계속 생각했어.'],['라나','부르고 싶은 거 불러.'],['토모리','응. 그런데 듣는 사람에게… 잘 전해질지 모르겠어.'],['토모리','게시판에서 누군가 쓴 말을 읽었을 때는… 그 사람이 어떤 마음인지 생각하게 됐어.'],['토모리','내가 부를 때도, 누군가 잠깐이라도 들어 줄까?'],['타키','모르더라도 불러 보자. 연습하면서 같이 들으면 되니까.'],['토모리','타키 쨩은… 먼저 들어 줄 거야?'],['타키','응. 네가 부르고 싶은 걸 듣고 싶어.'],['소요','곡 순서도 그다음에 정해도 늦지 않아.'],['토모리','…응. 먼저 불러 볼게.']]},
 concert_5:{title:'작은 공연 준비 ⑤ · 포스터',day:19,when:s=>s.stories.includes('concert_4'),lines:[['아논','포스터 시안 두 개! 어느 쪽이 좋아?'],['타키','이쪽은 공연 시간이 잘 보여. 다른 쪽은 제목이 눈에 들어오고.'],['아논','처음 보는 사람도 눈길이 갔으면 좋겠어서 색을 바꿔 봤어.'],['타키','색은 괜찮은데, 여기 날짜가 배경에 묻혀.'],['아논','아… 가까이서 만들 때는 몰랐네. 조금 뒤에서 보면 다르구나.'],['소요','입구에 붙여 보고 지나가면서 읽을 수 있는지 확인해 볼까?'],['아논','둘 다 살리고 싶은데 한 장에 넣으면 너무 복잡해지려나?'],['소요','멀리서 봐야 할 정보와 가까이서 읽을 정보를 나누면 어떨까.'],['아논','좋아. 날짜는 크게, 자세한 설명은 아래에 둘게.'],['토모리','빈자리에는… 게시판처럼 작은 선을 그려도 예쁠 것 같아.']]},
 concert_6:{title:'작은 공연 준비 ⑥ · 맞지 않는 박자',day:20,when:s=>s.stories.includes('concert_5'),lines:[['타키','한 번 더. 방금 전환하는 부분에서 박자가 밀렸어.'],['아논','알고 있어. 손을 바꾸는 게 아직 잘 안 돼.'],['타키','방금 전에도 같은 데서 멈췄잖아.'],['아논','그러니까 안다고! 빨리 넘어가려고 하면 손이 안 따라와.'],['소요','잠깐만. 어느 손가락을 먼저 옮기는지 보여 줄래?'],['아논','여기서 이쪽으로 가야 하는데… 다음 코드를 생각하면 늦어져.'],['타키','…그럼 속도를 낮추고 거기만 반복하자.'],['아논','다른 사람들 시간 뺏는 거 아니야?'],['타키','다 같이 맞추려고 하는 거야. 먼저 천천히 해 봐.'],['라나','내가 먼저 칠게. 듣고 들어와.'],['아논','…응. 이번엔 끝까지 놓치지 않을게.'],['소요','천천히 시작하자. 내가 박자 셀게.']]},
 concert_7:{title:'작은 공연 준비 ⑦ · 쉬는 시간',day:21,when:s=>s.stories.includes('concert_6'),lines:[['토모리','아노 쨩, 손 괜찮아?'],['아논','응. 아프진 않은데 생각보다 잘 안 돼서.'],['아논','다들 기다리는데 나만 계속 같은 데서 틀리니까 좀 그렇더라.'],['토모리','아노 쨩이… 그 부분 혼자 다시 연습하는 것도 봤어.'],['아논','봤어? 괜히 잘하는 척했나 싶네.'],['토모리','나는 잘하는 척이라고 생각하지 않았어.'],['토모리','나도 가끔… 전하고 싶은데 말이 안 나와.'],['아논','토모린도?'],['토모리','응. 그래서 다시 해 볼 시간을 주면… 조금 안심돼.'],['아논','그럼 나도 조금 쉬고 다시 해 볼래. 같이 기다려 줄래?'],['토모리','응.']]},
 concert_8:{title:'작은 공연 준비 ⑧ · 마지막 확인',day:22,when:s=>s.stories.includes('concert_7'),lines:[['타키','공연 날짜 확인했고, 포스터도 붙였어. 남은 건 당일 준비야.'],['아논','음료랑 케이크는 공연 전에 사람들이 몰릴 테니까 넉넉히 준비하자.'],['소요','너무 많이 남지 않게 예약과 지난번 판매량도 보자.'],['타키','모자라면 바로 품절 표시를 걸고, 다른 주문까지 늦지 않게 해야 해.'],['아논','그럼 메뉴판을 두 장 준비할게. 품절될 때 바꾸기 쉽게.'],['소요','필요한 수량은 나도 같이 확인해 줄게.'],['라나','기타는 가져왔어.'],['타키','아직 공연 당일 아니거든.'],['라나','알아. 연습하러 왔어.'],['토모리','그럼… 다 같이 맞춰 보자.']]},
 concert_9:{title:'작은 공연 준비 ⑨ · 무대 앞',day:23,when:s=>s.stories.includes('concert_8')&&liveDay(),lines:[['아논','객석 쪽에서 얘기하는 소리가 들려. 벌써 이렇게 많이 왔네.'],['타키','이제 곧 시작이야. 물 마셨지?'],['토모리','응. 조금 떨려.'],['타키','무대 올라가기 전에 숨 한번 고르자. 급하게 안 나가도 돼.'],['아논','나도 같이 할래. 막상 문 앞에 오니까 손이 차가워졌어.'],['라나','손, 보여 줘.'],['아논','왜? …앗, 갑자기 잡지 마!'],['라나','차갑네.'],['소요','떨려도 괜찮아. 우리가 같이 있잖아.'],['라나','가자.'],['아논','응. 오늘은 준비한 만큼 보여 주자!'],['타키','다들, 제자리로.']]},
 concert_10:{title:'작은 공연 준비 ⑩ · 끝나고 남은 말',day:24,when:s=>s.stories.includes('concert_9'),lines:[['아논','끝났다…! 이번에는 진짜 준비한 대로 된 것 같아.'],['타키','전환 부분도 맞았어. 연습한 보람이 있었네.'],['아논','그 말 녹음할 걸!','wink'],['타키','다시 안 말해. …그 부분은 전보다 잘 들렸어.'],['아논','응. 라나 쨩이 옆에서 쳐 준 거 계속 생각하면서 했거든.'],['라나','오늘은 안 멈췄어.'],['아논','그거 칭찬이지? 칭찬이라고 들을게!'],['소요','후후. 게시판에도 벌써 새 종이가 붙었어.'],['라나','읽어 봐.'],['토모리','…노래가 끝난 뒤에도, 여기에 남아 있고 싶었다고 써 있어.'],['타키','그럼 조금 더 있어도 되지. 마감까지는 아직 시간이 있으니까.'],['토모리','응. 우리도… 같이 있자.','smile']]}
};

